function onInit(self, engine) {
  // Physics properties
  self.vx = 0;
  self.vy = 0;
  self.speed = 200;
  self.jumpForce = -350;
  self.gravity = 800;
  self.grounded = false;

  // World bounds
  self.worldWidth = 800;
  self.worldHeight = 450;
  self.cellSize = 32;
  self.groundY = 11 * self.cellSize; // Row 11 is ground

  // Score
  self.score = 0;
}

function onUpdate(self, engine, dt) {
  // Horizontal movement
  var moveLeft = keyIsDown(65) || keyIsDown(LEFT_ARROW);
  var moveRight = keyIsDown(68) || keyIsDown(RIGHT_ARROW);
  var jump = keyIsDown(87) || keyIsDown(UP_ARROW) || keyIsDown(32);

  // Apply horizontal acceleration
  if (moveLeft) {
    self.vx = -self.speed;
  } else if (moveRight) {
    self.vx = self.speed;
  } else {
    self.vx = self.vx * 0.8; // Friction
    if (Math.abs(self.vx) < 1) self.vx = 0;
  }

  // Jump
  if (jump && self.grounded) {
    self.vy = self.jumpForce;
    self.grounded = false;
  }

  // Apply gravity
  self.vy = self.vy + self.gravity * dt;

  // Move and check collision
  var newX = self.x + self.vx * dt;
  var newY = self.y + self.vy * dt;

  // World bounds
  if (newX < 0) { newX = 0; self.vx = 0; }
  if (newX + self.width > self.worldWidth) { newX = self.worldWidth - self.width; self.vx = 0; }

  // Ground collision (simple - just check ground level)
  if (newY >= self.groundY - self.height) {
    newY = self.groundY - self.height;
    self.vy = 0;
    self.grounded = true;
  } else {
    self.grounded = false;
  }

  // Death (fall off screen)
  if (newY > self.worldHeight) {
    // Reset position
    newX = 64;
    newY = 200;
    self.vx = 0;
    self.vy = 0;
    self.score = 0;
  }

  // Coin collection
  var coins = engine.gameObjects.filter(function(o) { return o.type === 'coin'; });
  for (var i = 0; i < coins.length; i++) {
    var coin = coins[i];
    if (coin.active !== false && rectsOverlap(self.x, self.y, self.width, self.height, coin.x, coin.y, coin.width, coin.height)) {
      coin.active = false;
      coin.x = -100;
      coin.y = -100;
      self.score = (self.score || 0) + 10;
    }
  }

  self.x = newX;
  self.y = newY;
}

function rectsOverlap(x1, y1, w1, h1, x2, y2, w2, h2) {
  return x1 < x2 + w2 && x1 + w1 > x2 && y1 < y2 + h2 && y1 + h1 > y2;
}

function onInit(self, engine) {
  self.startY = self.y;
  self.bobOffset = Math.random() * Math.PI * 2;
}

function onUpdate(self, engine, dt) {
  if (self.active === false) return;

  // Floating animation
  self.y = self.startY + Math.sin(engine.elapsed * 3 + self.bobOffset) * 4;
}

function onInit(self, engine) {
  self.canvas = null;
}

function onUpdate(self, engine, dt) {
  // Find player
  var player = engine.findObject('obj_player');
  if (!player) return;

  // Draw HUD using p5.js
  if (typeof fill !== 'undefined' && typeof text !== 'undefined') {
    // Score
    fill('#fbbf24');
    noStroke();
    textSize(20);
    textAlign(LEFT, TOP);
    text('Score: ' + (player.score || 0), 16, 16);

    // Instructions
    fill('#94a3b8');
    textSize(12);
    text('WASD or Arrows to move/jump', 16, 42);

    // Win message
    if ((player.score || 0) >= 30) {
      fill('#4ade80');
      textSize(32);
      textAlign(CENTER, CENTER);
      text('YOU WIN!', 400, 200);
      textSize(16);
      text('Press R to restart', 400, 240);
    }

    // Restart
    if (keyIsDown(82)) { // R key
      player.x = 64;
      player.y = 200;
      player.vx = 0;
      player.vy = 0;
      player.score = 0;
      // Reset coins
      engine.gameObjects.forEach(function(o) {
        if (o.type === 'coin') {
          o.active = true;
          if (o.id === 'obj_coin') { o.x = 350; o.y = 280; }
          if (o.id === 'obj_coin2') { o.x = 500; o.y = 200; }
          if (o.id === 'obj_coin3') { o.x = 650; o.y = 120; }
        }
      });
    }
  }
}
